insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, published_at) values ('activity', 'male-city-mini-bus-tour', 'Male City Mini Bus Tour', 'Male City Mini Bus Tour is a guided sightseeing tour of Male, the Maldives'' capital island, by air-conditioned mini bus (up to ~15 seats), with airport pickup and drop-off. USD 150 per hour, minimum 2 hours. Includes: airport pickup and drop-off, local guide, mini bus, taxes. Highlights: Stingray Point, local market, fish market, souvenir street, Old Presidential Palace, Grand Friday Mosque, Victory Monument, Old Friday Mosque (heritage), Presidential Office, Parliament, Artificial Beach, surfing point, Tsunami Monument, King Salmaan Mosque, and the Sinamale Bridge.', 'published', 'Male City Mini Bus Tour (USD 150/hr) | Maldives Tour Guide', 'Male City Mini Bus Tour is a guided sightseeing tour of Male by air-conditioned mini bus, with airport pickup and drop-off. USD 150 per hour.', now()) on conflict (node_type, slug) do nothing;
insert into activities (id, activity_category, operated_by_provider_id, price_from, currency) select n.id, 'excursion', p.id, 150, 'USD' from nodes n, nodes p where n.node_type = 'activity' and n.slug = 'male-city-mini-bus-tour' and p.node_type = 'provider' and p.slug = 'maldives-tour-guide-tours' on conflict (id) do nothing;
insert into node_locations (node_id, location_id, relation) select n.id, l.id, 'primary' from nodes n, nodes l where n.node_type = 'activity' and n.slug = 'male-city-mini-bus-tour' and l.node_type = 'location' and l.slug = 'male' on conflict (node_id, location_id) do nothing;
insert into bookable_products (id, booking_mode, base_price, currency) select id, 'inquiry', 150, 'USD' from nodes where node_type = 'activity' and slug = 'male-city-mini-bus-tour' on conflict (id) do nothing;
insert into node_categories (node_id, category_id) select n.id, c.id from nodes n, nodes c where n.node_type = 'activity' and n.slug = 'male-city-mini-bus-tour' and c.node_type = 'category' and c.slug = 'city-tour' on conflict (node_id, category_id) do nothing;
insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, published_at) values ('activity', 'male-city-large-bus-tour', 'Male City Large Bus Tour', 'Male City Large Bus Tour is a guided sightseeing tour of Male, the Maldives'' capital island, by air-conditioned large bus (30+ seats), ideal for bigger groups, with airport pickup and drop-off. USD 200 per hour, minimum 2 hours. Includes: airport pickup and drop-off, local guide, large bus, taxes. Highlights: Stingray Point, local market, fish market, souvenir street, Old Presidential Palace, Grand Friday Mosque, Victory Monument, Old Friday Mosque (heritage), Presidential Office, Parliament, Artificial Beach, surfing point, Tsunami Monument, King Salmaan Mosque, and the Sinamale Bridge.', 'published', 'Male City Large Bus Tour (USD 200/hr) | Maldives Tour Guide', 'Male City Large Bus Tour is a guided sightseeing tour of Male by air-conditioned large bus, ideal for groups, with airport pickup and drop-off. USD 200 per hour.', now()) on conflict (node_type, slug) do nothing;
